package com.xiaoxiao.pet;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.android.controller.ActivityController;import android.view.*;import android.widget.*;import android.app.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @LooperMode(LooperMode.Mode.PAUSED)
public class UiTest {
 @Before public void init(){Data.app=null;Data.roles.clear();Data.init(RuntimeEnvironment.getApplication());Data.prefs().edit().clear().commit();AgentRuntime.cancel();AgentRuntime.memory=null;AgentRuntime.model=AgentTransport::request;PetService.instance=null;TestKeyStore.install();}
 @After public void cleanup()throws Exception{AgentRuntime.cancel();ShadowLooper.idleMainLooper();AgentRuntime.model=AgentTransport::request;Data.logWriter.submit(()->{}).get(5,TimeUnit.SECONDS);}
 @Test public void activityCreatesAndRenders(){MainActivity a=activity();assertNotNull(a.content);assertTrue(a.content.getChildCount()>3);assertEquals("大肥鱼",find(a.content,"大肥鱼").getText().toString());}
 @Test public void manualPersonaOnboardingAndReadOnlyUI(){MainActivity a=activity();Dialog d=dialog();assertEquals(6,all(d.getWindow().getDecorView(),RadioButton.class).size());View chosen=description(d.getWindow().getDecorView(),"初始人格：温柔陪伴");assertNotNull(chosen);chosen.performClick();click(d,"确认性格，开始陪伴");assertTrue(PersonaManager.isInitialized("main"));assertEquals("gentle",PersonaManager.activeId("main"));String frozen=PersonaManager.prompt("main");assertTrue(frozen.contains("温柔陪伴"));click(a.content,"她的性格 · 温柔陪伴");assertTrue(all(dialog().getWindow().getDecorView(),RadioButton.class).isEmpty());assertNull(find(dialog().getWindow().getDecorView(),"确认性格，开始陪伴"));assertEquals(frozen,PersonaManager.prompt("main"));}
 @Test public void randomChoiceOccursOnlyAtInitialization(){MainActivity a=activity();Dialog d=dialog();View option=description(d.getWindow().getDecorView(),"初始化随机人格");option.performClick();click(d,"确认性格，开始陪伴");String id=PersonaManager.activeId("main"),prompt=PersonaManager.prompt("main");assertEquals("random",PersonaManager.mode("main"));assertNotNull(PersonaManager.find(id));a.recreate();ShadowLooper.idleMainLooper();assertEquals(id,PersonaManager.activeId("main"));assertEquals(prompt,PersonaManager.prompt("main"));}
 @Test public void modelSettingsUIValidatesSavesAndKeepsAtomicConfiguration()throws Exception{MainActivity a=ready();click(a.content,"模型连接");AlertDialog d=(AlertDialog)dialog();List<EditText> fields=all(d.getWindow().getDecorView(),EditText.class);assertEquals(3,fields.size());fields.get(0).setText("http://invalid.example/v1");fields.get(1).setText("test-model");fields.get(2).setText("test-only-key");d.getButton(-1).performClick();assertTrue(d.isShowing());assertFalse(ModelSettings.complete());fields.get(0).setText("https://one.example/v1");d.getButton(-1).performClick();assertFalse(d.isShowing());assertTrue(ModelSettings.complete());ModelSettings.Config saved=ModelSettings.read();assertEquals("test-only-key",saved.secret);assertEquals("test-model",saved.model);assertFalse(Data.prefs().getString("api.secret","").contains("test-only-key"));Map<String,?> before=new HashMap<>(Data.prefs().getAll());click(a.content,"模型连接");d=(AlertDialog)dialog();fields=all(d.getWindow().getDecorView(),EditText.class);assertEquals("",fields.get(2).getText().toString());fields.get(0).setText("https://two.example/v1");fields.get(1).setText("other-model");d.getButton(-1).performClick();assertTrue(d.isShowing());assertEquals(before,Data.prefs().getAll());fields.get(0).setText("https://one.example/v1");d.getButton(-1).performClick();assertFalse(d.isShowing());assertEquals("other-model",ModelSettings.read().model);assertEquals("test-only-key",ModelSettings.read().secret);}
 @Test public void memoryEditorPersistsAndForgetsFromUI()throws Exception{MainActivity a=ready();click(a.content,"记忆手账");click(dialog(),"写下一条记忆");Dialog editor=dialog();List<EditText> edits=all(editor.getWindow().getDecorView(),EditText.class);edits.get(0).setText("我喜欢下雨天");((AlertDialog)editor).getButton(-1).performClick();JSONArray mem=AgentRuntime.store().snapshot().getJSONArray("memories");assertEquals(1,mem.length());assertEquals("我喜欢下雨天",mem.getJSONObject(0).getString("text"));click(dialog(),"★ 我喜欢下雨天");editor=dialog();((AlertDialog)editor).getButton(-3).performClick();((AlertDialog)dialog()).getButton(-1).performClick();ShadowLooper.idleMainLooper();assertEquals(0,AgentRuntime.store().snapshot().getJSONArray("memories").length());}
 @Test public void chatUIRunsPromptRecallStreamingAndCommitsControlledModelReply()throws Exception{MainActivity a=ready();ModelSettings.save("https://example.invalid/v1","controlled-model","test-only-key",false);final String[] prompt={null};AgentRuntime.model=(messages,token,progress)->{prompt[0]=messages.getJSONObject(0).getString("content");progress.accept("{\"reply\":\"蓝色，记住啦。");return "{\"reply\":\"蓝色，记住啦。\",\"emotion\":\"happy\",\"memories\":[\"我喜欢蓝色\"]}";};click(a.content,"和她聊聊");Dialog d=dialog();EditText input=all(d.getWindow().getDecorView(),EditText.class).get(0);input.setText("我喜欢蓝色");click(d,"发送");awaitIdle();assertTrue(prompt[0].contains("经典傲娇"));assertTrue(texts(d.getWindow().getDecorView()).contains("蓝色，记住啦。"));assertEquals(2,AgentRuntime.history().length());assertEquals(1,AgentRuntime.store().snapshot().getJSONArray("memories").length());assertEquals("happy",AgentRuntime.mood());assertTrue(AgentRuntime.context("我喜欢什么？",false).toString().contains("我喜欢蓝色"));}
 @Test public void failedModelRestoresDraftAndDoesNotCommit()throws Exception{MainActivity a=ready();ModelSettings.save("https://example.invalid/v1","controlled-model","test-only-key",false);AgentRuntime.model=(messages,token,progress)->{throw new java.io.IOException("controlled transport failure");};click(a.content,"和她聊聊");Dialog d=dialog();EditText input=all(d.getWindow().getDecorView(),EditText.class).get(0);input.setText("今天怎么样");click(d,"发送");awaitIdle();assertEquals("今天怎么样",input.getText().toString());assertTrue(input.isEnabled());assertTrue(texts(d.getWindow().getDecorView()).contains("controlled transport failure"));assertEquals(0,AgentRuntime.history().length());}
 @Test public void activityDestructionCancelsPendingConversation()throws Exception{ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();MainActivity a=controller.get();ShadowLooper.idleMainLooper();click(dialog(),"确认性格，开始陪伴");ModelSettings.save("https://example.invalid/v1","controlled-model","test-only-key",false);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AgentRuntime.model=(messages,token,progress)->{entered.countDown();release.await(10,TimeUnit.SECONDS);return "late result";};click(a.content,"和她聊聊");Dialog d=dialog();all(d.getWindow().getDecorView(),EditText.class).get(0).setText("待回复");click(d,"发送");try{assertTrue(entered.await(5,TimeUnit.SECONDS));controller.pause().stop().destroy();ShadowLooper.idleMainLooper();assertFalse("destroyed Activity must not leave AgentRuntime busy",AgentRuntime.busy());assertFalse("destroyed Activity chat window should close",d.isShowing());}finally{release.countDown();}}
 @Test public void personaPersistenceMigrationAndLockChecks()throws Exception{int n=PersonaChecks.run(RuntimeEnvironment.getApplication());System.out.println("PASS: "+n+" isolated persona checks");assertTrue(n>=30);}
 @Test public void cancelAfterCommittedReplyCompletesExactlyOnce()throws Exception{ready();ModelSettings.save("https://example.invalid/v1","controlled-model","test-only-key",false);AgentRuntime.model=(messages,token,progress)->"已完成的回复";Counter result=new Counter();AgentRuntime.send("你好",false,result);long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(AgentRuntime.history().length()==0&&System.nanoTime()<until)Thread.sleep(5);assertEquals(2,AgentRuntime.history().length());AgentRuntime.cancel();ShadowLooper.idleMainLooper();assertEquals(1,result.done);assertEquals(0,result.errors);assertEquals(2,AgentRuntime.history().length());}
 @Test public void openingManualChatInterruptsPendingProactiveRequest()throws Exception{MainActivity a=ready();ModelSettings.save("https://example.invalid/v1","controlled-model","test-only-key",false);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AgentRuntime.model=(messages,token,progress)->{entered.countDown();release.await(5,TimeUnit.SECONDS);return "主动消息";};Counter result=new Counter();AgentRuntime.send("",true,result);try{assertTrue(entered.await(3,TimeUnit.SECONDS));assertTrue(AgentRuntime.busy());click(a.content,"和她聊聊");assertFalse(AgentRuntime.busy());assertNotNull(find(dialog().getWindow().getDecorView(),"发送"));assertEquals(1,result.errors);}finally{release.countDown();}}
 @Test public void explicitMemoryAndItsSourceDisappearTogether()throws Exception{ready();Counter result=new Counter();AgentRuntime.send("记住：我喜欢下雨天",false,result);awaitIdle();assertEquals(1,result.done);JSONArray memories=AgentRuntime.store().snapshot().getJSONArray("memories");assertEquals(1,memories.length());assertEquals(2,AgentRuntime.history().length());AgentRuntime.store().forget(memories.getJSONObject(0).getString("id"));assertEquals(0,AgentRuntime.store().snapshot().getJSONArray("memories").length());assertEquals(0,AgentRuntime.history().length());assertFalse(AgentRuntime.context("你记得什么？",false).toString().contains("我喜欢下雨天"));}
 @Test public void nameAndNicknameUISaveIntoPromptWithoutChangingPersonality()throws Exception{MainActivity a=ready();String frozen=PersonaManager.prompt("main");click(a.content,"名字与称呼");AlertDialog d=(AlertDialog)dialog();EditText name=(EditText)description(d.getWindow().getDecorView(),"她的名字"),nickname=(EditText)description(d.getWindow().getDecorView(),"她对你的称呼");name.setText("小鲸");nickname.setText("小船长");d.getButton(-1).performClick();ShadowLooper.idleMainLooper();assertFalse(d.isShowing());assertEquals("小鲸",Data.name("main"));assertEquals("小船长",Data.prefs().getString("agent.nickname",""));String prompt=AgentRuntime.context("你好",false).toString();assertTrue(prompt.contains("小鲸"));assertTrue(prompt.contains("小船长"));assertEquals(frozen,PersonaManager.prompt("main"));click(a.content,"名字与称呼");d=(AlertDialog)dialog();assertEquals("小鲸",((EditText)description(d.getWindow().getDecorView(),"她的名字")).getText().toString());assertEquals("小船长",((EditText)description(d.getWindow().getDecorView(),"她对你的称呼")).getText().toString());}
 @Test public void companionSwitchesPersistAndMemoryFocusControlsAffectRuntime()throws Exception{MainActivity a=ready();AgentRuntime.store().remember("我喜欢海边散步");AgentRuntime.store().clear(false);assertTrue(AgentRuntime.context("你记得我吗",false).toString().contains("我喜欢海边散步"));click(a.content,"陪伴设置");AlertDialog d=(AlertDialog)dialog();View root=d.getWindow().getDecorView();assertTrue(((Switch)find(root,"记住重要的事")).isChecked());assertFalse(((Switch)find(root,"偶尔主动和我说话")).isChecked());assertTrue(((Switch)find(root,"边生成边显示")).isChecked());click(d,"记住重要的事");click(d,"偶尔主动和我说话");click(d,"边生成边显示");assertFalse(AgentRuntime.rememberEnabled());assertTrue(Data.prefs().getBoolean("agent.proactive",false));assertFalse(Data.prefs().getBoolean("agent.stream",true));assertFalse(AgentRuntime.context("你记得我吗",false).toString().contains("我喜欢海边散步"));assertEquals(1,AgentRuntime.store().snapshot().getJSONArray("memories").length());long before=System.currentTimeMillis();click(d,"安静陪伴 1 小时");assertTrue(Data.prefs().getLong("agent.focusUntil",0)>=before+3599000);d.getButton(-1).performClick();ShadowLooper.idleMainLooper();click(a.content,"陪伴设置");d=(AlertDialog)dialog();root=d.getWindow().getDecorView();assertFalse(((Switch)find(root,"记住重要的事")).isChecked());assertTrue(((Switch)find(root,"偶尔主动和我说话")).isChecked());assertFalse(((Switch)find(root,"边生成边显示")).isChecked());click(d,"结束安静陪伴");assertEquals(0,Data.prefs().getLong("agent.focusUntil",-1));}
 static final class Counter implements AgentRuntime.Listener{int done,errors,partial;public void partial(String text){partial++;}public void done(String text,String emotion){done++;}public void error(String text){errors++;}}
 static MainActivity activity(){MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();ShadowLooper.idleMainLooper();return a;}
 static MainActivity ready(){MainActivity a=activity();click(dialog(),"确认性格，开始陪伴");return a;}
 static Dialog dialog(){Dialog d=ShadowDialog.getLatestDialog();assertNotNull(d);return d;}
 static void click(Dialog d,String text){click(d.getWindow().getDecorView(),text);}
 static void click(View root,String text){TextView v=find(root,text);assertNotNull("Missing UI control: "+text,v);v.performClick();ShadowLooper.idleMainLooper();}
 static <T> List<T> all(View root,Class<T> type){List<T> out=new ArrayList<>();if(type.isInstance(root))out.add(type.cast(root));if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++)out.addAll(all(g.getChildAt(i),type));}return out;}
 static View description(View root,String text){if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){View found=description(g.getChildAt(i),text);if(found!=null)return found;}}return null;}
 static String texts(View root){StringBuilder b=new StringBuilder();for(TextView v:all(root,TextView.class))b.append(v.getText()).append('\n');return b.toString();}
 static void awaitIdle()throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(AgentRuntime.busy()&&System.nanoTime()<until){ShadowLooper.idleMainLooper();Thread.sleep(10);}ShadowLooper.idleMainLooper();assertFalse("runtime did not finish",AgentRuntime.busy());}
 static TextView find(View root,String s){if(root instanceof TextView&&s.equals(((TextView)root).getText().toString()))return (TextView)root;if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){TextView v=find(g.getChildAt(i),s);if(v!=null)return v;}}return null;}
}
